	private static final int UNOBSERVED_READERS = 1;
	private static final int ARRIVAL_READERS = 2;
	private static final int MAX_WORKERS = SHORT_READERS + UNOBSERVED_READERS + ARRIVAL_READERS + 1;
	private static final int PRE_GROWTH_READ_ROWS = 4;
	private static final int SHORT_READ_TAIL_READS = 8;
	private static final int LONG_OBSERVED_ROWS = 128;
