	private static final long PRE_SIZED_MAP_SIZE = 128L * 1024 * 1024;
	private static final long LONG_OBSERVED_DRAIN_TIMEOUT_MILLIS = 100;
	private static final long GROWTH_START_TIMEOUT_SECONDS = 10;
