	private static final IRI READ_SUBJECT = Values.iri("urn:rdf4j:lmdb-growth:read-subject");
	private static final IRI READ_PREDICATE = Values.iri("urn:rdf4j:lmdb-growth:read-predicate");
	private static final IRI OBSERVED_SUBJECT = Values.iri("urn:rdf4j:lmdb-growth:observed-subject");
	private static final IRI OBSERVED_PREDICATE = Values.iri("urn:rdf4j:lmdb-growth:observed-predicate");
